require_login();
$errors = [];
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$new=$_POST['new_password']??'';$confirm=$_POST['confirm_password']??'';
if($name==='')$errors[]='Full name is required.'; if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Please enter a valid email.'; if($new!==''&&strlen($new)<8)$errors[]='New password must be at least 8 characters.'; if($new!==$confirm)$errors[]='Password confirmation does not match.';
if(!$errors){$q=db()->prepare('SELECT id FROM users WHERE email=? AND id<>?');$q->execute([$email,user_id()]);if($q->fetch())$errors[]='This email is already registered.';else{$sql='UPDATE users SET full_name=?,email=?'.($new!==''?',password_hash=?':'').' WHERE id=?';$args=[$name,$email];if($new!=='')$args[]=password_hash($new,PASSWORD_DEFAULT);$args[]=user_id();db()->prepare($sql)->execute($args);$_SESSION['user_name']=$name;flash('Profile updated successfully.');header('Location: '.app_url('auth/profile.php'));exit;}} }
$q=db()->prepare('SELECT * FROM users WHERE id=?'); $q->execute([user_id()]); $u=$q->fetch();
